const body = $json.body ?? $json;
const required = ['reportId', 'targetType', 'targetId', 'reasonCode', 'reasonLabel', 'reportStatus'];
for (const key of required) {
  if (!body[key]) {
    throw new Error(`Missing required field: ${key}`);
  }
}
const targetType = String(body.targetType);
const allowedTypes = ['BLOG', 'COMMENT', 'USER', 'CAFE_PAGE'];
if (!allowedTypes.includes(targetType)) {
  throw new Error(`Unsupported targetType: ${targetType}`);
}
const aiContext = {
  reportId: body.reportId,
  targetType,
  targetId: body.targetId,
  reasonCode: body.reasonCode,
  reasonLabel: body.reasonLabel,
  reasonSeverity: Number(body.reasonSeverity ?? 1),
  description: body.description ?? '',
  contentText: body.contentText ?? '',
  imageUrls: Array.isArray(body.imageUrls) ? body.imageUrls.slice(0, 10) : [],
  reportStatus: body.reportStatus,
  existingModerationResult: body.existingModerationResult ?? null,
  sameTargetOpenReportCount: Number(body.sameTargetOpenReportCount ?? 0),
};
const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    reportDecision: { type: 'string', enum: ['RESOLVE', 'REJECT', 'NEEDS_MANUAL_REVIEW'] },
    targetAction: { type: 'string', enum: ['APPROVE', 'HIDE', 'REMOVE', 'KEEP_ACTIVE', 'SUSPEND_USER', 'SUSPEND_PAGE', 'NONE'] },
    confidenceScore: { type: 'number', minimum: 0, maximum: 100 },
    riskScore: { type: 'number', minimum: 0, maximum: 100 },
    labels: { type: 'array', items: { type: 'string' } },
    ruleCode: { type: 'string' },
    explanation: { type: 'string' }
  },
  required: ['reportDecision', 'targetAction', 'confidenceScore', 'riskScore', 'labels', 'ruleCode', 'explanation']
};
const policy = [
  'You recommend how an admin should resolve a CafeStory user report. You never execute actions.',
  'Allowed reportDecision values: RESOLVE, REJECT, NEEDS_MANUAL_REVIEW.',
  'BLOG/COMMENT: false or low risk -> REJECT + APPROVE; unclear -> NEEDS_MANUAL_REVIEW + NONE; clear violation -> RESOLVE + HIDE or REMOVE.',
  'USER: weak report -> REJECT + KEEP_ACTIVE; unclear -> NEEDS_MANUAL_REVIEW + NONE; severe repeated abuse -> RESOLVE + SUSPEND_USER.',
  'CAFE_PAGE: weak report -> REJECT + KEEP_ACTIVE; unclear -> NEEDS_MANUAL_REVIEW + NONE; severe page policy issue -> RESOLVE + SUSPEND_PAGE.',
  'Use REMOVE only for severe content that should not remain visible. Use HIDE for clear but less severe BLOG/COMMENT violations.',
  'sameTargetOpenReportCount and existingModerationResult can increase risk, but uncertainty should use NEEDS_MANUAL_REVIEW.'
].join('\n');
return [{
  json: {
    report: aiContext,
    openaiRequest: {
      model: $env.OPENAI_DECISION_MODEL || 'gpt-4o-mini',
      input: [
        {
          role: 'system',
          content: [
            { type: 'input_text', text: policy }
          ]
        },
        {
          role: 'user',
          content: [
            { type: 'input_text', text: JSON.stringify(aiContext, null, 2) }
          ]
        }
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'admin_report_ai_resolution',
          strict: true,
          schema
        }
      }
    }
  }
}];

const report = $('Validate And Build Decision Request').first().json.report;
function outputText(response) {
  if (typeof response.output_text === 'string') return response.output_text;
  const output = Array.isArray(response.output) ? response.output : [];
  for (const item of output) {
    const content = Array.isArray(item.content) ? item.content : [];
    for (const part of content) {
      if (typeof part.text === 'string') return part.text;
    }
  }
  return '';
}
function parseDecision(response) {
  const text = outputText(response).trim();
  if (!text) throw new Error('OpenAI response did not include output_text');
  return JSON.parse(text);
}
function clamp(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.min(100, numeric));
}
function allowedAction(targetType, action) {
  if (action === 'NONE') return true;
  if (['BLOG', 'COMMENT'].includes(targetType)) return ['APPROVE', 'HIDE', 'REMOVE'].includes(action);
  if (targetType === 'USER') return ['KEEP_ACTIVE', 'SUSPEND_USER'].includes(action);
  if (targetType === 'CAFE_PAGE') return ['KEEP_ACTIVE', 'SUSPEND_PAGE'].includes(action);
  return false;
}
const decision = parseDecision($json);
let reportDecision = decision.reportDecision;
let targetAction = decision.targetAction;
let ruleCode = decision.ruleCode || `${report.targetType}_AI_RECOMMENDATION`;
let explanation = decision.explanation || 'AI returned a structured recommendation.';
if (!allowedAction(report.targetType, targetAction)) {
  reportDecision = 'NEEDS_MANUAL_REVIEW';
  targetAction = 'NONE';
  ruleCode = 'INVALID_ACTION_FALLBACK';
  explanation = `AI returned invalid action for ${report.targetType}; manual review required.`;
}
return [{
  json: {
    reportDecision,
    targetAction,
    confidenceScore: clamp(decision.confidenceScore),
    riskScore: clamp(decision.riskScore),
    labels: Array.isArray(decision.labels) ? decision.labels.map(String) : [],
    ruleCode,
    explanation,
    modelName: $json.model || $env.OPENAI_DECISION_MODEL || 'gpt-4o-mini',
    rawResponse: {
      openaiResponseId: $json.id,
      reportId: report.reportId,
      targetType: report.targetType,
      targetId: report.targetId,
      sourceDecision: decision
    }
  }
}];
